    end

    if (this_block.port('per_din').width ~= 32);
      this_block.setError('Input data type for port "per_din" must have width=32.');
    end

    if (this_block.port('per_we').width ~= 1);
      this_block.setError('Input data type for port "per_we" must have width=1.');
    end

    this_block.port('per_we').useHDLVector(false);

    if (this_block.port('chnsel').width ~= 1);
      this_block.setError('Input data type for port "chnsel" must have width=1.');
